m","uneven_workload","delivery_person_finishes_early","one_delivery_person_overloaded","new_delivery_person_unfamiliar_with_area"]},{"category":"vehicle_pressure","op_ref":"OP-08","situations":["van_unavailable","motorcycle_unsuitable_for_load","car_already_full","bulky_order","fragile_order","mixed_vehicle_fleet"]},{"category":"planning_pressure","op_ref":"OP-05/OP-06","situations":["too_many_drops","unclear_grouping","manual_route_planning","wrong_delivery_grouping","delivery_window_conflict","difficult_service_area_split"]},{"category":"execution_pressure","op_ref":"OP-09/OP-12","situations":["traffic","rain","parking","gated_property","condominium_access","loading_bay_delay","customer_unavailable","wrong_address","cannot_find_entrance"]},{"category":"customer_communication","op_ref":"OP-11","situations":["order_status_question","driver_location_question","eta_question","instructions_changed","recipient_unavailable","staff_repeatedly_answering_delivery_questions"]},{"category":"owner_admin_pressure","op_ref":"OP-02/OP-14","situations":["whatsapp_overload","spreadsheet_chaos","manually_calling_delivery_team","checking_multiple_chats","trying_to_remember_which_orders_left","manually_dividing_orders","unclear_delivery_status"]}]},"emotionalTensions":{"taxonomy_version":"1.0","tensions":["urgency","uncertainty","responsibility","relief","frustration","confusion","time_pressure","overload","anticipation","satisfaction_when_operation_becomes_controlled"],"doctrine":"Understand operational emotion without exaggerating it. Avoid melodrama. Most CEFFLO tension should feel like 'macam mana nak settle ni', not a catastrophic business crisis."},"creativeFormats":{"taxonomy_version":"1.0","formats":["situational","pov","dialogue","ugc_style","product_in_context","product_demo","screen_recording","b_roll_narrative","educational","light_humour","static_carousel"],"doctrine":"One validated operational scenario should be reusable across several formats where appropriate -- see do